CREATE OR REPLACE FUNCTION public.resolve_import_identity(p_kind text,p_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Solo administradores'; END IF; IF p_kind='meet' THEN RETURN public.resolve_import_meet(p_data->>'name',(p_data->>'startDate')::date,(p_data->>'endDate')::date,p_data->>'location',p_data->>'course'); ELSIF p_kind='event' THEN RETURN public.resolve_import_event((p_data->>'meetId')::uuid,p_data->>'number',(p_data->>'distance')::integer,(p_data->>'stroke')::smallint,p_data->>'gender',(p_data->>'minAge')::integer,(p_data->>'maxAge')::integer); ELSE RAISE EXCEPTION 'Tipo de identidad no reconocido'; END IF; END; $$; REVOKE ALL ON FUNCTION public.resolve_import_identity(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resolve_import_identity(text,jsonb) TO authenticated,service_role;